stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_flow_variables",
      "evidence": "The demand at each retail outlet (in units) ... The supply capacity of each distribution center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"satisfy the demand at each retail outlet\"",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] = demand[j]"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_linkage_form",
      "evidence": "\"Each center has its own operating cost and supply capacity\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= bigM * y[i]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_scope",
      "evidence": "\"open the distribution centers and transport goods\" / \"minimum possible total cost\"",
      "options": [
        "minimize opening costs + transportation costs",
        "minimize transportation costs only"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "minimize opening costs + transportation costs"
    },
    {
      "decision": "opening_cost_units",
      "evidence": "\"The opening costs for each center are as follows (in dollars)\"",
      "options": [
        "use opening costs as given in dollars",
        "scale opening costs (e.g., thousands) before summing"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "use opening costs as given in dollars"
    },
    {
      "decision": "transport_cost_orientation",
      "evidence": "\"From Center 1: $5 to Outlet 1, $5 to Outlet 2, $2 to Outlet 3, $3 to Outlet 4\"",
      "options": [
        "transport_cost[(center, outlet)] as listed (rows=centers, cols=outlets)",
        "transport_cost[(outlet, center)] transposed"
      ],
      "plausibility": [
        0.98,
        0.02
      ],
      "majority_option": "transport_cost[(center, outlet)] as listed (rows=centers, cols=outlets)"
    }
  ]
}
